const items = $input.all();
const rows = items.map(i => i.json);

if (rows.length === 0) {
  return [{ json: { htmlReport: '<p>No data available for this period.</p>', summary: 'Empty' } }];
}

// Compute summary stats
const columns = Object.keys(rows[0]);
const numericCols = columns.filter(col => {
  return rows.some(r => !isNaN(parseFloat(r[col])));
});

let summaryRows = '';
const stats = {};
for (const col of numericCols) {
  const values = rows.map(r => parseFloat(r[col])).filter(v => !isNaN(v));
  if (values.length === 0) continue;
  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / values.length;
  const min = Math.min(...values);
  const max = Math.max(...values);
  stats[col] = { sum, avg, min, max, count: values.length };
  summaryRows += `<tr><td style="padding:8px;border:1px solid #ddd;font-weight:bold;">${col}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${values.length}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${sum.toFixed(2)}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${avg.toFixed(2)}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${min.toFixed(2)}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${max.toFixed(2)}</td></tr>`;
}

// Build data table (first 20 rows)
let dataHeaders = columns.map(c => `<th style="padding:8px;border:1px solid #ddd;background:#f3f4f6;">${c}</th>`).join('');
let dataRows = '';
const displayRows = rows.slice(0, 20);
for (const row of displayRows) {
  dataRows += '<tr>' + columns.map(c => `<td style="padding:6px;border:1px solid #ddd;">${row[c] || ''}</td>`).join('') + '</tr>';
}

const htmlReport = `<div style="font-family:Arial,sans-serif;max-width:800px;margin:auto;">
  <h2 style="color:#2563eb;">Weekly Report</h2>
  <p style="color:#666;">Generated: ${new Date().toISOString().split('T')[0]} | ${rows.length} records</p>

  <h3>Summary Statistics</h3>
  <table style="width:100%;border-collapse:collapse;margin:10px 0;">
    <thead><tr style="background:#2563eb;color:white;"><th style="padding:8px;">Metric</th><th style="padding:8px;">Count</th><th style="padding:8px;">Sum</th><th style="padding:8px;">Avg</th><th style="padding:8px;">Min</th><th style="padding:8px;">Max</th></tr></thead>
    <tbody>${summaryRows}</tbody>
  </table>

  <h3>Data Preview (first 20 rows)</h3>
  <table style="width:100%;border-collapse:collapse;margin:10px 0;font-size:0.85em;">
    <thead><tr>${dataHeaders}</tr></thead>
    <tbody>${dataRows}</tbody>
  </table>
  ${rows.length > 20 ? `<p style="color:#999;">... and ${rows.length - 20} more rows</p>` : ''}
</div>`;

return [{ json: { htmlReport, totalRows: rows.length, metricsCount: Object.keys(stats).length, generatedAt: new Date().toISOString() } }];
